", "t": [["write_file", "{"path":"D:\\Projects\\local_ai\\strata-lab\\runs\\work\\hermes\\jsondiff-1794053379\\jsondiff.py","content":"import json\n\n\ndef _equal(a, b):\n    \"\"\"Structural equality that treats values of different types as unequal.\"\"\"\n    if isinstance(a, dict) and isinstance(b, dict):\n        return a.keys() == b.keys() and all(_equal(a[k], b[k]) for k in a)\n    if isinstance(a, list) and isinstance(b, list):\n        return len(a) == len(b) and all(_equal(x, y) for x, y in zip(a, b))\n    return type(a) is type(b) and a == b\n\n\ndef _fmt(value):\n    return json.dumps(value, sort_keys=True)\n\n\ndef _walk(a, b, path, out):\n    if _equal(a, b):\n        return\n\n    if isinstance(a, dict) and isinstance(b, dict):\n        for k in a:\n            if k not in b:\n                out.append(\"- %s.%s: %s\" % (path, k, _fmt(a[k])))\n            else:\n                _walk(a[k], b[k], \"%s.%s\" % (path, k), out)\n        for k in b:\n            if k not in a:\n                out.append(\"+ %s.%s: %s\" % (path, k, _fmt(b[k])))\n        return\n\n    if isinstance(a, list) and isinstance(b, list):\n        n = min(len(a), len(b))\n        for i in range(n):\n            _walk(a[i], b[i], \"%s[%d]\" % (path, i), out)\n        for i in range(n, len(a)):\n            out.append(\"- %s[%d]: %s\" % (path, i, _fmt(a[i])))\n        for i in range(n, len(b)):\n            out.append(\"+ %s[%d]: %s\" % (path, i, _fmt(b[i])))\n        return\n\n    out.append(\"~ %s: %s -> %s\" % (path, _fmt(a), _fmt(b)))\n\n\ndef diff(a, b):\n    out = []\n    _walk(a, b, \"$\", out)\n    return sorted(out)\n"}"]]}

